import os,stat,sys
if len(sys.argv) != 3:
    raise SystemExit(64)
src,dst=sys.argv[1:3]
os.umask(0o022)
before=os.lstat(src)
if not stat.S_ISREG(before.st_mode) or before.st_nlink != 1:
    raise SystemExit(70)
s=os.open(src,os.O_RDONLY|os.O_CLOEXEC|os.O_NOFOLLOW)
try:
    opened=os.fstat(s)
    if (opened.st_dev,opened.st_ino) != (before.st_dev,before.st_ino) or not stat.S_ISREG(opened.st_mode) or opened.st_nlink != 1:
        raise SystemExit(71)
    d=os.open(dst,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_CLOEXEC|os.O_NOFOLLOW,0o644)
    try:
        made=os.fstat(d)
        if not stat.S_ISREG(made.st_mode) or stat.S_IMODE(made.st_mode) != 0o644 or made.st_nlink != 1 or (made.st_dev,made.st_ino) == (opened.st_dev,opened.st_ino):
            raise SystemExit(72)
        while True:
            chunk=os.read(s,1048576)
            if not chunk:
                break
            view=memoryview(chunk)
            while view:
                count=os.write(d,view)
                if count <= 0:
                    raise OSError("short write")
                view=view[count:]
        after=os.fstat(s)
        if (after.st_dev,after.st_ino,after.st_mode,after.st_nlink,after.st_size,after.st_mtime_ns) != (opened.st_dev,opened.st_ino,opened.st_mode,opened.st_nlink,opened.st_size,opened.st_mtime_ns):
            raise SystemExit(73)
        if os.fstat(d).st_size != after.st_size:
            raise SystemExit(74)
        os.fsync(d)
    finally:
        os.close(d)
finally:
    os.close(s)
